"""Amplitude of K in code E for the two histories m_f = 10 (Paper F, Sec. 'A strong pulse generated by collapse into an existing hole', Why the fold does not occur).
K(v=1500) on the ray U~1 (index 2) of genc_S5to10 and genc_S0to10, their ratio, and (B_0/B_5)^4 with the coefficients B of the two tables (strong_fit.log).
usage: strong_k1500.py genc_S5to10....json genc_S0to10....json B_S5 B_S0          (run in sp/)"""
import sys, json, os, numpy as np
sys.argv_ = sys.argv
sys.argv = [sys.argv[0]]                          # pscan_an prints a header at import time and loops over argv[1:]: import it with no files
import io, contextlib
with contextlib.redirect_stdout(io.StringIO()):
    sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
    import pscan_an
sys.argv = sys.argv_
f5, f0, b5, b0 = sys.argv[1], sys.argv[2], float(sys.argv[3]), float(sys.argv[4])
K = {}
for tag, f in (('S5to10', f5), ('S0to10', f0)):
    d = json.load(open(f)); v = np.array(d['vq']); hv = list(d['data'].keys())[-1]
    A = pscan_an.fields(d, hv, 2)
    i = int(np.argmin(abs(v - 1500)))
    K[tag] = float(A['K'][i])
    print('%s: K(v=%g) = %.3e' % (tag, v[i], K[tag]))
print('ratio K(S5to10)/K(S0to10) = %.3f ; (B_0/B_5)^4 = %.3f  (B_5 = %.1f, B_0 = %.1f)' % (K['S5to10'] / K['S0to10'], (b0 / b5) ** 4, b5, b0))
